using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns an HTTPS link to a topic in a forum supergroup chat. This is an offline method
    /// </summary>
    public Task<TdLib.TdApi.Objects.MessageLink> GetForumTopicLinkAsync(long chatId = default, int forumTopicId = default)
    {

           using var activity =  StartCallActivity("GetForumTopicLinkAsync", typeof(GetForumTopicLink).FullName ?? "GetForumTopicLinkAsync");

           try
           {
             return client.GetForumTopicLinkAsync(chatId, forumTopicId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
